package cz.playlingo.core

/**
 * Texty přihlášení účtem PlayStation přes telefon: kroky průvodce v televizi (pa_…), stránka,
 * kterou televize vystaví telefonu (wp_…), a PlayLingo v telefonu (hp_…).
 * LOGIN_S = čeština a slovenština, LOGIN_X = ostatní jazyky.
 */
internal val LOGIN_S: Map<String, Pair<String, String>> = mapOf(
    "pa_1_text" to ("PlayStation potřebuje vědět, ke kterému účtu se televize připojuje. Zjistí se to přihlášením k účtu PlayStation. Dělá se to v telefonu, jen jednou, a trvá to asi dvě minuty.\n\nOtevři v telefonu fotoaparát, namiř ho na čtvereček vlevo a klepni na odkaz, který se objeví. Otevře se stránka PlayLingo z této televize, proto musí být telefon na stejné Wi-Fi. Pak tady zvol Pokračovat." to "PlayStation potrebuje vedieť, ku ktorému účtu sa televízor pripája. Zistí sa to prihlásením k účtu PlayStation. Robí sa to v telefóne, len raz, a trvá to asi dve minúty.\n\nOtvor v telefóne fotoaparát, namier ho na štvorček vľavo a ťukni na odkaz, ktorý sa objaví. Otvorí sa stránka PlayLingo z tohto televízora, preto musí byť telefón na rovnakej Wi-Fi. Potom tu zvoľ Pokračovať."),
    "pa_2_text" to ("1. V telefonu se přihlas DRUHÝM účtem PlayStation.\n2. Když se stránka zeptá na „passkey“, zvol Remind Me Later.\n3. Zkopíruj adresu prázdné stránky „redirect“ a vlož ji na stránce PlayLingo. Televize pak pokračuje sama." to "1. V telefóne sa prihlás DRUHÝM účtom PlayStation.\n2. Keď sa stránka opýta na „passkey“, zvoľ Remind Me Later.\n3. Skopíruj adresu prázdnej stránky „redirect“ a vlož ju na stránke PlayLingo. Televízor potom pokračuje sám."),
    "pa_3_title" to ("Nejde to? Opiš kód ručně" to "Nejde to? Opíš kód ručne"),
    "pa_3_text" to ("Tenhle krok je jen záloha. Když adresa vložená v telefonu projde, televize ho přeskočí sama.\n\nV telefonu klepni nahoře na adresu té prázdné stránky. Je dlouhá – najdi v ní „code=“. Kód je to, co následuje hned za ním, až po znak &. Opiš ho do políčka přesně, i s tečkou a velkými písmeny, a zvol Ověřit kód. Kód platí jen pár minut." to "Tento krok je len záloha. Keď adresa vložená v telefóne prejde, televízor ho preskočí sám.\n\nV telefóne ťukni hore na adresu tej prázdnej stránky. Je dlhá – nájdi v nej „code=“. Kód je to, čo nasleduje hneď za ním, až po znak &. Opíš ho do políčka presne, aj s bodkou a veľkými písmenami, a zvoľ Overiť kód. Kód platí len pár minút."),
    "pa_nolan" to ("Stránku pro telefon se teď nepodařilo vystavit, čtvereček proto vede rovnou na přihlášení Sony. Po přihlášení opiš kód ručně v dalším kroku." to "Stránku pre telefón sa teraz nepodarilo vystaviť, štvorček preto vedie priamo na prihlásenie Sony. Po prihlásení opíš kód ručne v ďalšom kroku."),
    "wp_web_h" to ("Přihlášení v prohlížeči" to "Prihlásenie v prehliadači"),
    "wp_1" to ("1. Klepni na tlačítko. Přihlášení Sony se otevře na nové kartě." to "1. Ťukni na tlačidlo. Prihlásenie Sony sa otvorí na novej karte."),
    "wp_login_btn" to ("Přihlásit se u PlayStation" to "Prihlásiť sa u PlayStation"),
    "wp_2" to ("2. Přihlas se DRUHÝM účtem. Když se stránka zeptá na „passkey“, zvol Remind Me Later. Nakonec zůstane skoro prázdná stránka se slovem „redirect“. Klepni nahoře na její adresu, zvol Kopírovat a vrať se na tuto kartu." to "2. Prihlás sa DRUHÝM účtom. Keď sa stránka opýta na „passkey“, zvoľ Remind Me Later. Nakoniec zostane takmer prázdna stránka so slovom „redirect“. Ťukni hore na jej adresu, zvoľ Kopírovať a vráť sa na túto kartu."),
    "wp_3" to ("3. Vlož zkopírovanou adresu sem:" to "3. Vlož skopírovanú adresu sem:"),
    "wp_send" to ("Odeslat do televize" to "Odoslať do televízora"),
    "wp_ok" to ("Hotovo ✔ Účet je ověřený. Pokračuj na televizi." to "Hotovo ✔ Účet je overený. Pokračuj na televízore."),
    "wp_bad" to ("Adresa neplatí nebo už vypršela (platí jen pár minut). Přihlas se znovu a vlož novou." to "Adresa neplatí alebo už vypršala (platí len pár minút). Prihlás sa znova a vlož novú."),
    "wp_gone" to ("Televize už na tomto odkazu nečeká. Otevři na ní znovu krok se čtverečkem a naskenuj ho znovu." to "Televízor už na tomto odkaze nečaká. Otvor na ňom znova krok so štvorčekom a naskenuj ho znova."),
    "wp_app_h" to ("Máš PlayLingo i v telefonu?" to "Máš PlayLingo aj v telefóne?"),
    "wp_app_text" to ("Aplikace v telefonu (jen Android) se přihlásí sama, nic se nekopíruje a účet si zapamatuje pro příště." to "Aplikácia v telefóne (len Android) sa prihlási sama, nič sa nekopíruje a účet si zapamätá nabudúce."),
    "wp_app_btn" to ("Otevřít v aplikaci PlayLingo" to "Otvoriť v aplikácii PlayLingo"),
    "wp_app_get" to ("Stáhnout PlayLingo do telefonu" to "Stiahnuť PlayLingo do telefónu"),
    "hp_title" to ("Přihlášení pro televizi" to "Prihlásenie pre televízor"),
    "hp_intro" to ("Tady se přihlásíš účtem PlayStation a telefon ho pošle do televize. Účet si zapamatuje, takže příště stačí jedno klepnutí. Heslo zadáváš přímo na stránce Sony; aplikace si ukládá jen číslo účtu." to "Tu sa prihlásiš účtom PlayStation a telefón ho pošle do televízora. Účet si zapamätá, takže nabudúce stačí jedno ťuknutie. Heslo zadávaš priamo na stránke Sony; aplikácia si ukladá len číslo účtu."),
    "hp_scan" to ("Na televizi otevři v PlayLingu krok se čtverečkem, naskenuj ho fotoaparátem telefonu a na stránce zvol „Otevřít v aplikaci PlayLingo“." to "Na televízore otvor v PlayLingu krok so štvorčekom, naskenuj ho fotoaparátom telefónu a na stránke zvoľ „Otvoriť v aplikácii PlayLingo“."),
    "hp_tv_ready" to ("Televize čeká na účet ✔" to "Televízor čaká na účet ✔"),
    "hp_login_top" to ("Přihlas se DRUHÝM účtem PlayStation (ne tím, na kterém hraješ). Když se stránka zeptá na „passkey“, zvol Remind Me Later." to "Prihlás sa DRUHÝM účtom PlayStation (nie tým, na ktorom hráš). Keď sa stránka opýta na „passkey“, zvoľ Remind Me Later."),
    "hp_saved" to ("Uložené účty" to "Uložené účty"),
    "hp_forget" to ("Zapomenout" to "Zabudnúť"),
    "hp_sent" to ("Hotovo ✔ Účet je v televizi. Pokračuj tam." to "Hotovo ✔ Účet je v televízore. Pokračuj tam."),
    "hp_send_fail" to ("Televize neodpovídá. Telefon musí být na stejné Wi-Fi jako televize a na televizi musí být otevřený krok se čtverečkem. Naskenuj čtvereček znovu." to "Televízor neodpovedá. Telefón musí byť na rovnakej Wi-Fi ako televízor a na televízore musí byť otvorený krok so štvorčekom. Naskenuj štvorček znova."),
    "hp_browser" to ("Nejde to? Přihlásit se v prohlížeči" to "Nejde to? Prihlásiť sa v prehliadači"),
    "hp_browser_text" to ("Přihlas se v prohlížeči. Na skoro prázdné stránce se slovem „redirect“ zvol Sdílet a vyber PlayLingo." to "Prihlás sa v prehliadači. Na takmer prázdnej stránke so slovom „redirect“ zvoľ Zdieľať a vyber PlayLingo."),
    "hp_is_tv" to ("Tohle je televize nebo box" to "Toto je televízor alebo box"),
    "hp_lg_title" to ("Mám televizi LG" to "Mám televízor LG"),
    "hp_lg_text" to ("Televize LG si titulky ze hry sama nepřečte. Tento telefon je může číst, překládat a posílat do televize – v televizi k tomu spusť PlayLingo." to "Televízor LG si titulky z hry sám neprečíta. Tento telefón ich môže čítať, prekladať a posielať do televízora – v televízore na to spusti PlayLingo."),
    "hp_lg_btn" to ("Použít telefon pro televizi LG" to "Použiť telefón pre televízor LG"),
    "hp_back" to ("Zpět do režimu telefonu (pomocník pro přihlášení)" to "Späť do režimu telefónu (pomocník na prihlásenie)"),
    "hp_acc" to ("Účet PlayStation" to "Účet PlayStation"),
)

internal val LOGIN_X: Map<Lang, Map<String, String>> = mapOf(
    Lang.EN to mapOf(
        "pa_1_text" to "The PlayStation needs to know which account the TV connects with. This is found out by signing in to the PlayStation account. It is done on a phone, only once, and takes about two minutes.\n\nOpen the camera on your phone, point it at the square on the left and tap the link that appears. A PlayLingo page from this TV opens, so the phone must be on the same Wi-Fi. Then choose Continue here.",
        "pa_2_text" to "1. On the phone, sign in with the SECOND PlayStation account.\n2. When the page asks about a “passkey”, choose Remind Me Later.\n3. Copy the address of the empty “redirect” page and paste it on the PlayLingo page. The TV then continues by itself.",
        "pa_3_title" to "Not working? Type the code by hand",
        "pa_3_text" to "This step is only a fallback. When the address pasted on the phone is accepted, the TV skips it by itself.\n\nOn the phone, tap the address of that empty page at the top. It is long – find “code=” in it. The code is what follows right after it, up to the & character. Type it into the field exactly, including the dot and capital letters, and choose Check the code. The code is valid for only a few minutes.",
        "pa_nolan" to "The page for the phone could not be served right now, so the square leads straight to the Sony sign-in. After signing in, type the code by hand in the next step.",
        "wp_web_h" to "Sign in using the browser",
        "wp_1" to "1. Tap the button. The Sony sign-in opens in a new tab.",
        "wp_login_btn" to "Sign in to PlayStation",
        "wp_2" to "2. Sign in with the SECOND account. When the page asks about a “passkey”, choose Remind Me Later. In the end an almost empty page with the word “redirect” remains. Tap its address at the top, choose Copy and return to this tab.",
        "wp_3" to "3. Paste the copied address here:",
        "wp_send" to "Send to TV",
        "wp_ok" to "Done ✔ The account is verified. Continue on the TV.",
        "wp_bad" to "The address is not valid or has expired (it is valid for only a few minutes). Sign in again and paste the new one.",
        "wp_gone" to "The TV is no longer waiting on this link. Open the step with the square on it again and scan it once more.",
        "wp_app_h" to "Do you have PlayLingo on your phone too?",
        "wp_app_text" to "The app on the phone (Android only) signs in by itself, nothing is copied, and it remembers the account for next time.",
        "wp_app_btn" to "Open in the PlayLingo app",
        "wp_app_get" to "Download PlayLingo to the phone",
        "hp_title" to "Sign-in for the TV",
        "hp_intro" to "Here you sign in with a PlayStation account and the phone sends it to the TV. It remembers the account, so next time one tap is enough. You enter the password directly on the Sony page; the app stores only the account number.",
        "hp_scan" to "On the TV, open the step with the square in PlayLingo, scan it with the phone’s camera and choose “Open in the PlayLingo app” on the page.",
        "hp_tv_ready" to "The TV is waiting for the account ✔",
        "hp_login_top" to "Sign in with the SECOND PlayStation account (not the one you play on). When the page asks about a “passkey”, choose Remind Me Later.",
        "hp_saved" to "Saved accounts",
        "hp_forget" to "Forget",
        "hp_sent" to "Done ✔ The account is on the TV. Continue there.",
        "hp_send_fail" to "The TV is not responding. The phone must be on the same Wi-Fi as the TV and the step with the square must be open on the TV. Scan the square again.",
        "hp_browser" to "Not working? Sign in using the browser",
        "hp_browser_text" to "Sign in using the browser. On the almost empty page with the word “redirect” choose Share and pick PlayLingo.",
        "hp_is_tv" to "This is a TV or a TV box",
        "hp_lg_title" to "I have an LG TV",
        "hp_lg_text" to "An LG TV cannot read the game’s subtitles itself. This phone can read them, translate them and send them to the TV – start PlayLingo on the TV for that.",
        "hp_lg_btn" to "Use this phone for the LG TV",
        "hp_back" to "Back to phone mode (sign-in helper)",
        "hp_acc" to "PlayStation account",
    ),
    Lang.PL to mapOf(
        "pa_1_text" to "PlayStation musi wiedzieć, z którym kontem łączy się telewizor. Ustala się to przez zalogowanie na konto PlayStation. Robi się to w telefonie, tylko raz, i trwa około dwóch minut.\n\nOtwórz w telefonie aparat, skieruj go na kwadrat po lewej i stuknij link, który się pojawi. Otworzy się strona PlayLingo z tego telewizora, dlatego telefon musi być w tej samej sieci Wi-Fi. Potem wybierz tutaj Dalej.",
        "pa_2_text" to "1. Zaloguj się w telefonie DRUGIM kontem PlayStation.\n2. Gdy strona zapyta o „passkey”, wybierz Remind Me Later.\n3. Skopiuj adres pustej strony „redirect” i wklej go na stronie PlayLingo. Telewizor przejdzie dalej sam.",
        "pa_3_title" to "Nie działa? Przepisz kod ręcznie",
        "pa_3_text" to "Ten krok to tylko zapas. Gdy adres wklejony w telefonie zostanie przyjęty, telewizor pominie go sam.\n\nW telefonie stuknij u góry adres tej pustej strony. Jest długi – znajdź w nim „code=”. Kod to to, co następuje zaraz po nim, aż do znaku &. Przepisz go w polu dokładnie, z kropką i wielkimi literami, i wybierz Sprawdź kod. Kod jest ważny tylko kilka minut.",
        "pa_nolan" to "Nie udało się teraz udostępnić strony dla telefonu, dlatego kwadrat prowadzi prosto do logowania Sony. Po zalogowaniu przepisz kod ręcznie w następnym kroku.",
        "wp_web_h" to "Logowanie w przeglądarce",
        "wp_1" to "1. Stuknij przycisk. Logowanie Sony otworzy się na nowej karcie.",
        "wp_login_btn" to "Zaloguj się w PlayStation",
        "wp_2" to "2. Zaloguj się DRUGIM kontem. Gdy strona zapyta o „passkey”, wybierz Remind Me Later. Na końcu zostanie prawie pusta strona ze słowem „redirect”. Stuknij jej adres u góry, wybierz Kopiuj i wróć na tę kartę.",
        "wp_3" to "3. Wklej tutaj skopiowany adres:",
        "wp_send" to "Wyślij do telewizora",
        "wp_ok" to "Gotowe ✔ Konto zweryfikowane. Przejdź do telewizora.",
        "wp_bad" to "Adres jest nieprawidłowy albo wygasł (jest ważny tylko kilka minut). Zaloguj się ponownie i wklej nowy.",
        "wp_gone" to "Telewizor nie czeka już pod tym linkiem. Otwórz na nim ponownie krok z kwadratem i zeskanuj go jeszcze raz.",
        "wp_app_h" to "Masz PlayLingo także w telefonie?",
        "wp_app_text" to "Aplikacja w telefonie (tylko Android) zaloguje się sama, niczego się nie kopiuje, a konto zapamięta na następny raz.",
        "wp_app_btn" to "Otwórz w aplikacji PlayLingo",
        "wp_app_get" to "Pobierz PlayLingo na telefon",
        "hp_title" to "Logowanie dla telewizora",
        "hp_intro" to "Tutaj zalogujesz się kontem PlayStation, a telefon wyśle je do telewizora. Konto zostanie zapamiętane, więc następnym razem wystarczy jedno stuknięcie. Hasło wpisujesz bezpośrednio na stronie Sony; aplikacja zapisuje tylko numer konta.",
        "hp_scan" to "Na telewizorze otwórz w PlayLingo krok z kwadratem, zeskanuj go aparatem telefonu i wybierz na stronie „Otwórz w aplikacji PlayLingo”.",
        "hp_tv_ready" to "Telewizor czeka na konto ✔",
        "hp_login_top" to "Zaloguj się DRUGIM kontem PlayStation (nie tym, na którym grasz). Gdy strona zapyta o „passkey”, wybierz Remind Me Later.",
        "hp_saved" to "Zapisane konta",
        "hp_forget" to "Zapomnij",
        "hp_sent" to "Gotowe ✔ Konto jest w telewizorze. Przejdź do niego.",
        "hp_send_fail" to "Telewizor nie odpowiada. Telefon musi być w tej samej sieci Wi-Fi co telewizor, a na telewizorze musi być otwarty krok z kwadratem. Zeskanuj kwadrat ponownie.",
        "hp_browser" to "Nie działa? Zaloguj się w przeglądarce",
        "hp_browser_text" to "Zaloguj się w przeglądarce. Na prawie pustej stronie ze słowem „redirect” wybierz Udostępnij i wskaż PlayLingo.",
        "hp_is_tv" to "To jest telewizor albo przystawka",
        "hp_lg_title" to "Mam telewizor LG",
        "hp_lg_text" to "Telewizor LG sam nie odczyta napisów z gry. Ten telefon może je czytać, tłumaczyć i wysyłać do telewizora – uruchom w tym celu PlayLingo w telewizorze.",
        "hp_lg_btn" to "Użyj telefonu dla telewizora LG",
        "hp_back" to "Wróć do trybu telefonu (pomocnik logowania)",
        "hp_acc" to "Konto PlayStation",
    ),
    Lang.DE to mapOf(
        "pa_1_text" to "Die PlayStation muss wissen, mit welchem Konto sich der Fernseher verbindet. Das klärt sich durch die Anmeldung beim PlayStation-Konto. Das machst du am Handy, nur einmal, und es dauert etwa zwei Minuten.\n\nÖffne am Handy die Kamera, richte sie auf das Quadrat links und tippe auf den Link, der erscheint. Es öffnet sich die PlayLingo-Seite dieses Fernsehers, deshalb muss das Handy im selben WLAN sein. Wähle danach hier Weiter.",
        "pa_2_text" to "1. Melde dich am Handy mit dem ZWEITEN PlayStation-Konto an.\n2. Wenn die Seite nach einem „Passkey“ fragt, wähle Remind Me Later.\n3. Kopiere die Adresse der leeren Seite „redirect“ und füge sie auf der PlayLingo-Seite ein. Der Fernseher macht dann von selbst weiter.",
        "pa_3_title" to "Klappt es nicht? Code von Hand eingeben",
        "pa_3_text" to "Dieser Schritt ist nur eine Reserve. Wird die am Handy eingefügte Adresse angenommen, überspringt ihn der Fernseher von selbst.\n\nTippe am Handy oben auf die Adresse dieser leeren Seite. Sie ist lang – suche darin „code=“. Der Code ist das, was direkt danach folgt, bis zum Zeichen &. Gib ihn im Feld genau ein, mit Punkt und Großbuchstaben, und wähle Code prüfen. Der Code gilt nur wenige Minuten.",
        "pa_nolan" to "Die Seite fürs Handy konnte gerade nicht bereitgestellt werden, das Quadrat führt deshalb direkt zur Sony-Anmeldung. Gib den Code nach der Anmeldung im nächsten Schritt von Hand ein.",
        "wp_web_h" to "Anmeldung im Browser",
        "wp_1" to "1. Tippe auf die Schaltfläche. Die Sony-Anmeldung öffnet sich in einem neuen Tab.",
        "wp_login_btn" to "Bei PlayStation anmelden",
        "wp_2" to "2. Melde dich mit dem ZWEITEN Konto an. Wenn die Seite nach einem „Passkey“ fragt, wähle Remind Me Later. Am Ende bleibt eine fast leere Seite mit dem Wort „redirect“. Tippe oben auf ihre Adresse, wähle Kopieren und komm zu diesem Tab zurück.",
        "wp_3" to "3. Füge die kopierte Adresse hier ein:",
        "wp_send" to "An den Fernseher senden",
        "wp_ok" to "Fertig ✔ Das Konto ist bestätigt. Mach am Fernseher weiter.",
        "wp_bad" to "Die Adresse ist ungültig oder abgelaufen (sie gilt nur wenige Minuten). Melde dich erneut an und füge die neue ein.",
        "wp_gone" to "Der Fernseher wartet unter diesem Link nicht mehr. Öffne dort erneut den Schritt mit dem Quadrat und scanne es noch einmal.",
        "wp_app_h" to "Hast du PlayLingo auch auf dem Handy?",
        "wp_app_text" to "Die App auf dem Handy (nur Android) meldet sich selbst an, es wird nichts kopiert, und sie merkt sich das Konto fürs nächste Mal.",
        "wp_app_btn" to "In der PlayLingo-App öffnen",
        "wp_app_get" to "PlayLingo aufs Handy laden",
        "hp_title" to "Anmeldung für den Fernseher",
        "hp_intro" to "Hier meldest du dich mit dem PlayStation-Konto an, und das Handy schickt es an den Fernseher. Das Konto wird gemerkt, beim nächsten Mal genügt ein Tippen. Das Passwort gibst du direkt auf der Sony-Seite ein; die App speichert nur die Kontonummer.",
        "hp_scan" to "Öffne am Fernseher in PlayLingo den Schritt mit dem Quadrat, scanne es mit der Handykamera und wähle auf der Seite „In der PlayLingo-App öffnen“.",
        "hp_tv_ready" to "Der Fernseher wartet auf das Konto ✔",
        "hp_login_top" to "Melde dich mit dem ZWEITEN PlayStation-Konto an (nicht mit dem, auf dem du spielst). Wenn die Seite nach einem „Passkey“ fragt, wähle Remind Me Later.",
        "hp_saved" to "Gespeicherte Konten",
        "hp_forget" to "Vergessen",
        "hp_sent" to "Fertig ✔ Das Konto ist auf dem Fernseher. Mach dort weiter.",
        "hp_send_fail" to "Der Fernseher antwortet nicht. Das Handy muss im selben WLAN sein wie der Fernseher, und am Fernseher muss der Schritt mit dem Quadrat geöffnet sein. Scanne das Quadrat noch einmal.",
        "hp_browser" to "Klappt es nicht? Im Browser anmelden",
        "hp_browser_text" to "Melde dich im Browser an. Wähle auf der fast leeren Seite mit dem Wort „redirect“ Teilen und dann PlayLingo.",
        "hp_is_tv" to "Das ist ein Fernseher oder eine TV-Box",
        "hp_lg_title" to "Ich habe einen LG-Fernseher",
        "hp_lg_text" to "Ein LG-Fernseher kann die Untertitel des Spiels nicht selbst lesen. Dieses Handy kann sie lesen, übersetzen und an den Fernseher senden – starte dazu PlayLingo auf dem Fernseher.",
